CREATE OR REPLACE FUNCTION get_donor_renal_score(donor_id text)
RETURNS numeric AS $$
BEGIN
    RETURN (
        SELECT ROUND(CAST(
            (CAST(SUBSTRING(f.don_gfr_val FROM '^[0-9]+\.?[0-9]*') AS numeric) * 1.0) - 
            (CAST(SUBSTRING(f.don_crtn_val FROM '^[0-9]+\.?[0-9]*') AS numeric) * 10.0)
        AS numeric), 2)
        FROM function_and_recovery f
        WHERE f.recov_don_registry = donor_id
    );
END;
$$ LANGUAGE plpgsql;

